    using System;
using System.Collections.Generic;

// Custom MinHeap class
class MinHeap {
    private List<(int freq, int val)> heap = new List<(int, int)>();

    private void Swap(int i, int j) {
        var temp = heap[i];
        heap[i] = heap[j];
        heap[j] = temp;
    }

    private void HeapifyUp(int index) {
        while (index > 0) {
            int parent = (index - 1) / 2;
            if (Compare(heap[index], heap[parent]) < 0) {
                Swap(index, parent);
                index = parent;
            } else break;
        }
    }

    private void HeapifyDown(int index) {
        int n = heap.Count;
        while (true) {
            int left = 2 * index + 1;
            int right = 2 * index + 2;
            int smallest = index;

            if (left < n && Compare(heap[left], heap[smallest]) < 0)
                smallest = left;
            if (right < n && Compare(heap[right], heap[smallest]) < 0)
                smallest = right;

            if (smallest != index) {
                Swap(index, smallest);
                index = smallest;
            } else break;
        }
    }

    // Compare by frequency, then by value
    private int Compare((int freq, int val) a, (int freq, int val) b) {
        if (a.freq != b.freq) return a.freq - b.freq;
        return a.val - b.val;
    }

    public void Add(int val, int freq) {
        heap.Add((freq, val));
        HeapifyUp(heap.Count - 1);
    }

    public (int freq, int val) Pop() {
        var top = heap[0];
        heap[0] = heap[heap.Count - 1];
        heap.RemoveAt(heap.Count - 1);
        if (heap.Count > 0) HeapifyDown(0);
        return top;
    }

    public (int freq, int val) Peek() {
        return heap[0];
    }

    public int Count() {
        return heap.Count;
    }
}

